window.ARCANA_TR = function(str, lang){
  lang = lang || (document.documentElement.lang || 'en');
  const T = window.ARCANA_TERMS[lang];
  if(!str || !T || !T.exact) return str;
  if(T.exact[str] != null) return T.exact[str];
  let out = String(str);
  const toks = Object.keys(T.tokens).sort((a,b)=>b.length-a.length);
  for(const en of toks) if(out.indexOf(en)>-1) out = out.split(en).join(T.tokens[en]);
  return out;
};
window.ATELIX_supplierText = function(factory, field, lang){
  lang = lang || (document.documentElement.lang || 'en');
  const localized = factory && factory.copyI18n && factory.copyI18n[lang];
  const value = localized && localized[field];
  if(value != null && String(value).trim()) return String(value);
  const fallbackField = field === 'description' ? 'bio' : field;
  return factory && factory[fallbackField] != null ? String(factory[fallbackField]) : '';
};
/* translate a UI label */
window.ARCANA_T = function(key, lang){
  lang = lang || (document.documentElement.lang || 'en');
  const T = window.ARCANA_TERMS[lang];
  if(!T || !T.ui || T.ui[key]==null) return key;
  return T.ui[key];
};
window.ATELIX_publicValue = function(value, lang){
  const present = Array.isArray(value)
    ? value.filter(item=>String(item||'').trim()).length > 0
    : value != null && String(value).trim() !== '' && String(value).trim() !== '—';
  if(!present) return window.ARCANA_T('Contact supplier', lang);
  return Array.isArray(value) ? value.filter(Boolean).join(', ') : String(value);
};
/* localise a USD amount to the active currency */
window.ARCANA_money = function(usd, lang){
  lang = lang || (document.documentElement.lang || 'en');
  const f = window.ARCANA_FX[lang] || window.ARCANA_FX.en;
  const raw = Number(usd||0) * f.rate;
  const increment = Number(f.increment)||0.01;
  const v = Math.ceil((raw - Number.EPSILON) / increment) * increment;
  return f.sym + v.toLocaleString(f.loc, {minimumFractionDigits:f.dec, maximumFractionDigits:f.dec});
};
window.ATELIX_currencyMoney = function(amount, lang){
  lang = lang || (document.documentElement.lang || 'en');
  const f = window.ARCANA_FX[lang] || window.ARCANA_FX.en;
  return f.sym + Number(amount||0).toLocaleString(f.loc,{minimumFractionDigits:f.dec,maximumFractionDigits:f.dec});
};
window.ATELIX_productAmount = function(product, quantity, lang){
  lang = lang || (document.documentElement.lang || 'en');
  quantity = Number(quantity == null ? 1 : quantity);
  const currency = lang === 'ja' ? 'JPY' : lang === 'zh' ? 'CNY' : 'USD';
  const direct = product && product.catalogPrices && Number(product.catalogPrices[currency]);
  if(Number.isFinite(direct) && direct > 0) return direct*quantity;
  const f = window.ARCANA_FX[lang] || window.ARCANA_FX.en;
  const raw = Number(product&&product.price||0)*f.rate;
  const increment = Number(f.increment)||0.01;
  return Math.ceil((raw-Number.EPSILON)/increment)*increment*quantity;
};
window.ATELIX_productMoney = function(product, quantity, lang){
  return window.ATELIX_currencyMoney(window.ATELIX_productAmount(product,quantity,lang),lang);
};
/* tiered QC/insurance rates — below US$1000 subtotal vs. US$1000 and above */
window.ARCANA_addonRates = function(subtotal){
  const under = subtotal < 1000;
  return { qc: under ? 0.02 : 0.01, ins: under ? 0.01 : 0.005 };
};
